import type { ProgramEntry } from '../../types/mol';

export type CompactProgramG = [
  number, // rowNumber
  string, // mosid
  string, // occupation
  string, // command
  string, // program
  string, // institution
  string, // meetsMajority
  string, // length
  string, // province
  string, // appendix
  string, // noteRef
  string, // accreditationType
  string, // location
  string, // publicPrivate
  string[] // resolvedNoteKeys
];

export function expandListGRows(shardPrefix: string, rows: CompactProgramG[]): ProgramEntry[] {
  return rows.map((r) => ({
    id: `G-${shardPrefix}-${r[0]}`,
    tableId: 'G',
    rowNumber: r[0],
    mosid: r[1],
    occupation: r[2],
    command: r[3],
    program: r[4],
    institution: r[5],
    meetsMajority: r[6],
    length: r[7],
    province: r[8],
    appendix: r[9],
    noteRef: r[10],
    accreditationType: r[11],
    location: r[12],
    publicPrivate: r[13],
    resolvedNoteKeys: r[14],
  }));
}

